/**
 * Fetches recent news headlines for a stock via Google News' public RSS
 * feed — no API key needed. Used to give the AI extra context (beyond
 * pure technical indicators) when a stock is trading near its recent low,
 * so it can factor in whether the news around it looks likely to help it
 * recover or push it further down.
 *
 * Every item keeps its real source, publication date and link. Nothing
 * here is generated by AI — these are headlines exactly as published.
 */
const cheerio = require("cheerio");
const { timedFetch } = require("./net");

const HEADERS = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
};

function normalizeTitle(t) {
  return t.toLowerCase().replace(/\s+-\s+[^-]+$/, "").replace(/[^a-z0-9\u0600-\u06FF ]+/g, " ").replace(/\s+/g, " ").trim();
}

/** Parses an RSS document into [{ title, pubDate, link, source }], de-duplicated. */
function parseNewsRss(xml, limit = 5) {
  const $ = cheerio.load(xml, { xmlMode: true });
  const seen = new Set();
  const items = [];

  $("item").each((_, el) => {
    if (items.length >= limit) return;
    const title = $(el).find("title").first().text().trim();
    if (!title) return;

    const key = normalizeTitle(title);
    if (seen.has(key)) return; // same story syndicated by several outlets
    seen.add(key);

    items.push({
      title,
      pubDate: $(el).find("pubDate").first().text().trim(),
      link: $(el).find("link").first().text().trim(),
      source: $(el).find("source").first().text().trim(),
    });
  });

  return items;
}

async function fetchNews(symbol, limit = 5) {
  const query = encodeURIComponent(`${symbol} PSX Pakistan stock`);
  const url = `https://news.google.com/rss/search?q=${query}&hl=en-PK&gl=PK&ceid=PK:en`;

  try {
    const resp = await timedFetch(url, { headers: HEADERS }, 4000);
    if (!resp.ok) return [];
    return parseNewsRss(await resp.text(), limit);
  } catch {
    return []; // news is a nice-to-have — never let it break the main analysis
  }
}

module.exports = { fetchNews, parseNewsRss };
